import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Both 'interval' and 'duration' must be greater than zero.")

    start_time = time.time()
    end_time = start_time + duration

    try:
        with open(LOGFILE_PATH, 'w') as logfile:
            while time.time() < end_time:
                current_time = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
                cpu_usage = get_cpu_usage()
                log_entry = {
                    "timestamp": current_time,
                    "cpu_usage": cpu_usage
                }
                logfile.write(json.dumps(log_entry) + "\n")
                time.sleep(interval)
    except IOError as e:
        print(f"An IOError occurred: {e}")
        return None

    return LOGFILE_PATH
def get_cpu_usage():
    if platform.system() == "Windows":
        # Use 'wmic' command to get CPU usage on Windows
        result = subprocess.run(['wmic', 'cpu', 'get', 'loadpercentage'], capture_output=True, text=True)
        lines = result.stdout.strip().split('\n')
        if len(lines) > 1:
            return int(lines[1].strip())
    else:
        # Use 'top' command to get CPU usage on Unix/Linux
        result = subprocess.run(['top', '-bn1', '-i', '0.1'], capture_output=True, text=True)
        lines = result.stdout.strip().split('\n')
        for line in lines:
            if "%Cpu(s)" in line:
                parts = line.split(',')
                for part in parts:
                    if 'id' in part:
                        idle = float(part.split()[0].strip('%'))
                        return 100 - idle
    return 0

